smart.css:
.smc-root {
  color: var(--smc-text);
  background: var(--smc-bg);
  font-family: var(--smc-font-body);
  font-size: 16px;
  line-height: 1.75;
}

.smc-root h2,
.smc-root h3 {
  color: var(--smc-primary);
  font-family: var(--smc-font-heading);
  font-weight: 700;
  line-height: 1.3;
}

.smc-root h2 { font-size: clamp(24px, 3.6vw, 32px); }
.smc-root h3 { font-size: 18px; }
.smc-root p { margin: 0 0 14px; }
.smc-root a { color: var(--smc-accent); font-weight: 600; text-decoration: underline; }
.smc-root a:hover { color: var(--smc-primary); }

.smc-eyebrow {
  color: var(--smc-accent);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: .12em;
  text-transform: uppercase;
  margin: 0 0 8px;
}

.smc-intro {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 24px;
  padding: 28px 20px;
  background: color-mix(in srgb, var(--smc-primary) 7%, var(--smc-bg));
  border: 1px solid color-mix(in srgb, var(--smc-primary) 16%, var(--smc-border));
  border-radius: var(--smc-radius);
}

.smc-intro-copy h2 { margin: 0 0 16px; }
.smc-intro-copy p:last-child { margin-bottom: 0; }
.smc-intro-media { margin: 0; }
.smc-intro-media img {
  display: block;
  width: 100%;
  aspect-ratio: 590 / 479;
  object-fit: cover;
  border-radius: var(--smc-radius);
  background: var(--smc-bg);
  cursor: zoom-in;
}
.smc-intro-media figcaption {
  color: var(--smc-muted);
  font-size: 13px;
  line-height: 1.5;
  margin-top: 8px;
  text-align: center;
}

.smc-section { padding: 44px 0 0; }
.smc-section-heading { max-width: 720px; margin-bottom: 22px; }
.smc-section-heading h2,
.smc-spec-copy h2 { margin: 0 0 12px; }
.smc-section-heading p { color: var(--smc-muted); margin: 0; }

.smc-feature-grid,
.smc-use-grid,
.smc-zone-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 16px;
}

.smc-feature-card,
.smc-zone-card {
  padding: 22px;
  background: var(--smc-surface);
  border: 1px solid var(--smc-border);
  border-radius: var(--smc-radius);
}

.smc-feature-number {
  display: inline-block;
  padding: 3px 10px;
  background: color-mix(in srgb, var(--smc-accent) 12%, var(--smc-bg));
  color: var(--smc-accent);
  border-radius: 999px;
  font-size: 12px;
  font-weight: 700;
  margin-bottom: 12px;
}

.smc-feature-card h3,
.smc-zone-card h3 { margin: 0 0 8px; }
.smc-feature-card p,
.smc-zone-card p { color: var(--smc-muted); margin: 0; }

.smc-zone-badge {
  display: inline-block;
  margin-bottom: 10px;
  padding: 4px 10px;
  background: color-mix(in srgb, var(--smc-primary) 12%, var(--smc-bg));
  color: var(--smc-primary);
  border-radius: 6px;
  font-size: 13px;
  font-weight: 700;
}

.smc-spec-wrap {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 24px;
}

.smc-spec-media {
  margin: 16px 0 0;
  padding: 14px;
  background: var(--smc-surface);
  border: 1px solid var(--smc-border);
  border-radius: var(--smc-radius);
}
.smc-spec-media img {
  display: block;
  width: 100%;
  height: auto;
  border-radius: var(--smc-radius);
  cursor: zoom-in;
}
.smc-spec-media figcaption {
  color: var(--smc-muted);
  font-size: 13px;
  line-height: 1.5;
  margin-top: 8px;
  text-align: center;
}

.smc-table-scroll { overflow-x: auto; }
.smc-spec-table {
  width: 100%;
  min-width: 480px;
  border-collapse: separate;
  border-spacing: 0;
  overflow: hidden;
  border: 1px solid var(--smc-border);
  border-radius: var(--smc-radius);
  background: var(--smc-bg);
}
.smc-spec-table th,
.smc-spec-table td {
  padding: 13px 16px;
  border-bottom: 1px solid var(--smc-border);
  text-align: left;
  vertical-align: top;
}
.smc-spec-table th {
  color: var(--smc-bg);
  background: var(--smc-primary);
  font-weight: 700;
}
.smc-spec-table td:first-child { width: 36%; font-weight: 700; color: var(--smc-primary); }
.smc-spec-table tr:last-child td { border-bottom: 0; }

.smc-use-card {
  overflow: hidden;
  background: var(--smc-surface);
  border: 1px solid var(--smc-border);
  border-radius: var(--smc-radius);
  display: flex;
  flex-direction: column;
}
.smc-use-card img {
  display: block;
  width: 100%;
  aspect-ratio: 4 / 3;
  object-fit: contain;
  background: var(--smc-bg);
  padding: 12px;
  border-bottom: 1px solid var(--smc-border);
  cursor: zoom-in;
}
.smc-use-copy { padding: 20px; }
.smc-use-copy h3 { margin: 0 0 8px; }
.smc-use-copy p { color: var(--smc-muted); margin: 0; }

.smc-care {
  margin-top: 44px;
  padding: 28px 20px;
  background: color-mix(in srgb, var(--smc-accent) 6%, var(--smc-bg));
  border: 1px solid color-mix(in srgb, var(--smc-accent) 16%, var(--smc-border));
  border-radius: var(--smc-radius);
}

.smc-care-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 24px;
  align-items: center;
}

.smc-care-media {
  margin: 0;
  padding: 14px;
  background: var(--smc-bg);
  border: 1px solid var(--smc-border);
  border-radius: var(--smc-radius);
}
.smc-care-media img {
  display: block;
  width: 100%;
  height: auto;
  border-radius: var(--smc-radius);
  cursor: zoom-in;
}
.smc-care-media figcaption {
  color: var(--smc-muted);
  font-size: 13px;
  line-height: 1.5;
  margin-top: 8px;
  text-align: center;
}

.smc-steps { list-style: none; margin: 0; padding: 0; }
.smc-steps li {
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr);
  gap: 14px;
  padding: 16px 0;
  border-bottom: 1px solid var(--smc-border);
}
.smc-steps li:last-child { border-bottom: 0; }
.smc-step-index {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  color: var(--smc-bg);
  background: var(--smc-accent);
  border-radius: 50%;
  font-weight: 700;
}
.smc-steps h3 { margin: 2px 0 6px; }
.smc-steps p { color: var(--smc-muted); margin: 0; }

.smc-note {
  margin-top: 20px;
  padding: 18px;
  background: var(--smc-bg);
  border-left: 4px solid var(--smc-accent);
  border-radius: var(--smc-radius);
}
.smc-note strong { color: var(--smc-primary); display: block; margin-bottom: 4px; }
.smc-note p { margin: 0; color: var(--smc-muted); }

.smc-faq details {
  border-top: 1px solid var(--smc-border);
  padding: 16px 0;
}
.smc-faq details:last-child { border-bottom: 1px solid var(--smc-border); }
.smc-faq summary {
  color: var(--smc-primary);
  font-family: var(--smc-font-heading);
  font-weight: 700;
  font-size: 17px;
  cursor: pointer;
}
.smc-faq details p { color: var(--smc-muted); margin: 10px 0 0; }

.smc-related {
  margin-top: 44px;
  padding: 22px;
  background: var(--smc-surface);
  border: 1px solid var(--smc-border);
  border-radius: var(--smc-radius);
}
.smc-related strong { color: var(--smc-primary); display: block; margin-bottom: 10px; }
.smc-related-links { display: flex; flex-wrap: wrap; gap: 10px 14px; }
.smc-related-links a {
  display: inline-block;
  padding: 6px 14px;
  background: var(--smc-bg);
  border: 1px solid var(--smc-border);
  border-radius: 999px;
  text-decoration: none;
  font-size: 14px;
}
.smc-related-links a:hover {
  border-color: var(--smc-primary);
  color: var(--smc-primary);
}

.smc-root.smc-js [data-smc-reveal] {
  opacity: 0;
  transform: translateY(14px);
  transition: opacity .45s ease, transform .45s ease;
}
.smc-root.smc-js [data-smc-reveal].is-visible { opacity: 1; transform: none; }

@container smc (min-width: 700px) {
  .smc-intro { grid-template-columns: 1.05fr .95fr; padding: 32px; align-items: center; }
  .smc-feature-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .smc-zone-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .smc-spec-wrap { grid-template-columns: .9fr 1.1fr; align-items: start; }
  .smc-use-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .smc-care { padding: 34px; }
  .smc-care-grid { grid-template-columns: 1.05fr .95fr; }
}

@container smc (max-width: 420px) {
  .smc-root { font-size: 15px; }
  .smc-section { padding-top: 34px; }
  .smc-intro { padding: 20px 16px; }
  .smc-care { padding: 22px 16px; }
}

